from typing import List, Optional

class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

class Solution:
    def generateTrees(self, n: int) -> List[Optional[TreeNode]]:
        if n == 0:
            return []

        def build(start: int, end: int) -> List[Optional[TreeNode]]:
            if start > end:
                return [None]
            trees = []
            for val in range(start, end + 1):
                left_trees = build(start, val - 1)
                right_trees = build(val + 1, end)
                for left in left_trees:
                    for right in right_trees:
                        root = TreeNode(val, left, right)
                        trees.append(root)
            return trees

        return build(1, n)

class Solution {
public:
    vector<TreeNode*> generateTrees(int n) {
        if (n == 0) return {};
        return build(1, n);
    }
private:
    vector<TreeNode*> build(int start, int end) {
        if (start > end) return {nullptr};
        vector<TreeNode*> trees;
        for (int val = start; val <= end; val++) {
            auto left_trees = build(start, val - 1);
            auto right_trees = build(val + 1, end);
            for (auto left : left_trees) {
                for (auto right : right_trees) {
                    trees.push_back(new TreeNode(val, left, right));
                }
            }
        }
        return trees;
    }
};

class Solution {
    public List<TreeNode> generateTrees(int n) {
        if (n == 0) return new ArrayList<>();
        return build(1, n);
    }

    private List<TreeNode> build(int start, int end) {
        List<TreeNode> trees = new ArrayList<>();
        if (start > end) {
            trees.add(null);
            return trees;
        }
        for (int val = start; val <= end; val++) {
            List<TreeNode> leftTrees = build(start, val - 1);
            List<TreeNode> rightTrees = build(val + 1, end);
            for (TreeNode left : leftTrees) {
                for (TreeNode right : rightTrees) {
                    trees.add(new TreeNode(val, left, right));
                }
            }
        }
        return trees;
    }
}

/**
 * @param {number} n
 * @return {TreeNode[]}
 */
var generateTrees = function(n) {
    if (n === 0) return [];
    function build(start, end) {
        if (start > end) return [null];
        const trees = [];
        for (let val = start; val <= end; val++) {
            const leftTrees = build(start, val - 1);
            const rightTrees = build(val + 1, end);
            for (const left of leftTrees) {
                for (const right of rightTrees) {
                    trees.push({ val, left, right });
                }
            }
        }
        return trees;
    }
    return build(1, n);
};
